pub const ITEM_COINS: u32 = 500;
/// `ItemTaskType.SellBackpack`.
pub const ITEM_TASK_SELL_BACKPACK: u8 = 104;
/// `ActabilityType.Commerce`.
pub const ACTABILITY_COMMERCE: i32 = 31;

