/// `CSSellBackpackGoodsPacket`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CSSellBackpackGoodsPacket {
    pub obj_id: u32,
}

impl ClientPacket for CSSellBackpackGoodsPacket {
    const NAME: &'static str = "CSSellBackpackGoodsPacket";

    fn read(s: &mut PacketStream) -> Result<Self> {
        Ok(Self {
            obj_id: s.read_bc()?,
        })
    }

    fn handle<'a>(
        self,
        server: &'a GameServer,
        conn: &'a mut GameConnection,
    ) -> BoxFuture<'a, Result<()>> {
        Box::pin(async move {
            let Some(me) = conn.active_char.clone() else {
                return Ok(());
            };
            let base_price = sell_specialty(server, &me, self.obj_id);
            tracing::warn!(
                "CSSellBackpackGoods, ObjId: {}. BasePrice: {base_price}",
                self.obj_id
            );
            Ok(())
        })
    }
}

/// `CSSpecialtyRatioPacket`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CSSpecialtyRatioPacket {
    pub id: u32,
}

impl ClientPacket for CSSpecialtyRatioPacket {
    const NAME: &'static str = "CSSpecialtyRatioPacket";

    fn read(s: &mut PacketStream) -> Result<Self> {
        Ok(Self { id: s.read_u32()? })
    }

    fn handle<'a>(
        self,
        server: &'a GameServer,
        conn: &'a mut GameConnection,
    ) -> BoxFuture<'a, Result<()>> {
        Box::pin(async move {
            let Some(me) = conn.active_char.clone() else {
                return Ok(());
            };
            let ratio = ratio_for_specialty(server, &me);
            me.send(SCSpecialtyRatioPacket { ratio });
            Ok(())
        })
    }
}

