/// `CSRequestSpecialtyCurrentPacket`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CSRequestSpecialtyCurrentPacket {
    pub from_zone_group_id: u16,
    pub to_zone_group_id: u16,
}

impl ClientPacket for CSRequestSpecialtyCurrentPacket {
    const NAME: &'static str = "CSRequestSpecialtyCurrentPacket";

    fn read(s: &mut PacketStream) -> Result<Self> {
        Ok(Self {
            from_zone_group_id: s.read_u16()?,
            to_zone_group_id: s.read_u16()?,
        })
    }

    fn handle<'a>(
        self,
        server: &'a GameServer,
        conn: &'a mut GameConnection,
    ) -> BoxFuture<'a, Result<()>> {
        Box::pin(async move {
            let Some(me) = conn.active_char.clone() else {
                return Ok(());
            };
            let results = ratios_for_target_route(
                server,
                u32::from(self.from_zone_group_id),
                u32::from(self.to_zone_group_id),
            );
            me.send(SCSpecialtyCurrentPacket {
                from_zone_group: self.from_zone_group_id,
                to_zone_group: self.to_zone_group_id,
                results,
            });
            Ok(())
        })
    }
}

